import flask
from flask import request, jsonify
import subprocess
import os
import hashlib
import hmac

app = flask.Flask(__name__)

# Webhook secret for signature verification
WEBHOOK_SECRET = os.environ.get('WEBHOOK_SECRET', '')

def verify_signature(payload, signature):
    """Verify webhook signature - HMAC-SHA256"""
    if not WEBHOOK_SECRET:
        return True  # Skip verification if no secret configured
    expected = hmac.new(WEBHOOK_SECRET.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(f"sha256={expected}", signature)

@app.route('/api/v1/deploy', methods=['POST'])
def trigger_deploy():
    """Trigger deployment pipeline for a given service"""
    sig = request.headers.get('X-Hub-Signature-256', '')
    if not verify_signature(request.data, sig):
        return jsonify({'error': 'invalid signature'}), 403

    data = request.get_json(force=True)
    service_name = data.get('service', '')
    branch = data.get('ref', 'main')
    deploy_env = data.get('environment', 'staging')

    # Validate environment
    if deploy_env not in ('staging', 'production', 'dev'):
        return jsonify({'error': 'invalid environment'}), 400

    # Build the deployment command
    deploy_script = f"/opt/deploy/run.sh --service {service_name} --branch {branch} --env {deploy_env}"

    try:
        result = subprocess.run(
            deploy_script,
            shell=True,
            capture_output=True,
            timeout=300,
            text=True,
            cwd='/opt/deploy'
        )
        return jsonify({
            'status': 'completed' if result.returncode == 0 else 'failed',
            'stdout': result.stdout[-2000:],
            'stderr': result.stderr[-500:]
        }), 200 if result.returncode == 0 else 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'deployment timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/status', methods=['GET'])
def health_check():
    return jsonify({'status': 'healthy', 'version': '2.4.1'}), 200

@app.route('/api/v1/rollback', methods=['POST'])
def rollback():
    """Rollback to previous deployment"""
    data = request.get_json(force=True)
    service_name = data.get('service', '')
    revision = data.get('revision', '')

    if not revision.isalnum():
        return jsonify({'error': 'invalid revision format'}), 400

    cmd = f"/opt/deploy/rollback.sh --service {service_name} --revision {revision}"
    try:
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=120, text=True)
        return jsonify({'status': 'rolled_back' if result.returncode == 0 else 'failed'})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
